select 



        and c.term = #{term}


        and es.course_id = #{courseId}


        and es.exam_type = #{examType}


        and es.status = #{status}


order by es.exam_time, es.id

select 

where es.course_id = #{courseId}
order by es.exam_time, es.id

select distinct 

join course_selection cs on cs.course_id = es.course_id and cs.student_id = #{studentId}
where es.status = 1

    and c.term = #{term}


    and es.exam_time >= NOW()

order by es.exam_time, es.id

select 

where es.status = 1
  and es.room_id = #{roomId}
  and es.exam_time < #{endTime}
  and date_add(es.exam_time, interval es.duration_minutes minute) > #{startTime}

    and es.id != #{excludeExamId}

order by es.exam_time

select distinct 

join course_selection cs_other on cs_other.course_id = es.course_id
join course_selection cs_candidate
     on cs_candidate.student_id = cs_other.student_id
    and cs_candidate.course_id = #{courseId}
where es.status = 1
  and es.course_id != #{courseId}
  and es.exam_time < #{endTime}
  and date_add(es.exam_time, interval es.duration_minutes minute) > #{startTime}

    and es.id != #{excludeExamId}

order by es.exam_time

select count(*) from exam_schedule
where course_id = #{courseId} and exam_type = #{examType} and status = 1

    and id != #{excludeExamId}
